    if n <= 0:
        return False
    return n > 0 and (n & (n - 1) == 0) and (n & 1 == 1) # Incorrect check for power of 3, use log or iterative division

def is_power_of_3_correct(n):
    if n == 1:
        return True
    if n <= 0 or n % 3 != 0:
        return False
    while n > 1:
        n //= 3
    return n == 1

def solve_p3_search(max_val=20):
    solutions = []
    for a in range(1, max_val + 1):
        for b in range(a, max_val + 1):
            # Check a^2 + b = 3^x
            expr1 = a*a + b
            if is_power_of_3_correct(expr1):
                # Check b^2 + a = 3^y
                expr2 = b*b + a
                if is_power_of_3_correct(expr2):
                    solutions.append((a, b))
    return solutions

results = solve_p3_search()
