import math

def is_power_of_5(n):
    if n <= 0:
        return False
    # Check if the number is divisible by 5 until it's not, and check if the result is 1.
    while n > 1 and n % 5 == 0:
        n //= 5
    return n == 1

# Constraints: p=5, 1 <= a <= b <= 10, 5 does not divide a or b.
solutions = []
possible_values = [i for i in range(1, 11) if i % 5 != 0]

print(f"Searching for solutions for p=5 with 1 <= a <= b <= 10 and 5 not dividing a or b.")
print("-" * 50)

for a in possible_values:
    for b in possible_values:
        if a > b:
            continue

        # Condition 1: a^4 + b = 5^x
        expr1 = a**4 + b
        if is_power_of_5(expr1):
            # Condition 2: b^4 + a = 5^y
            expr2 = b**4 + a
            if is_power_of_5(expr2):
                solutions.append((a, b))
                print(f"Found solution: (a, b) = ({a}, {b})")
                print(f"  Check 1: {a}^4 + {b} = {expr1} = 5^x (x={math.log(expr1, 5) if expr1 > 0 else 'N/A'})")
                print(f"  Check 2: {b}^4 + {a} = {expr2} = 5^y (y={math.log(expr2, 5) if expr2 > 0 else 'N/A'})")
                print("-" * 50)

if not solutions:
    print("No solutions found in the specified range.")
else:
    print(f"Total solutions found: {solutions}")
